enhanced_schema:
{
  "tables": [
    {
      "table_name": "tokens",
      "columns": [
        {
          "name": "token_id",
          "type": "VARCHAR",
          "description": "Unique identifier for each token"
        },
        {
          "name": "name",
          "type": "VARCHAR",
          "description": "Name of the token"
        },
        {
          "name": "symbol",
          "type": "VARCHAR",
          "description": "Symbol of the token"
        },
        {
          "name": "decimals",
          "type": "INTEGER",
          "description": "Number of decimal places for the token"
        },
        {
          "name": "creator_address",
          "type": "VARCHAR",
          "description": "Address of the token creator"
        },
        {
          "name": "initial_supply",
          "type": "FLOAT",
          "description": "Initial supply of the token"
        },
        {
          "name": "current_supply",
          "type": "FLOAT",
          "description": "Current total supply of the token"
        },
        {
          "name": "token_type",
          "type": "VARCHAR",
          "description": "Type of the token (e.g., ERC20, ERC721)"
        },
        {
          "name": "creation_date",
          "type": "DATE",
          "description": "Date when the token was created"
        },
        {
          "name": "is_verified",
          "type": "BOOLEAN",
          "description": "Indicates if the token is verified"
        }
      ],
      "primary_key": [
        "token_id"
      ]
    },
    {
      "table_name": "transactions",
      "columns": [
        {
          "name": "transaction_id",
          "type": "VARCHAR",
          "description": "Unique identifier for each transaction"
        },
        {
          "name": "token_id",
          "type": "VARCHAR",
          "description": "ID of the token involved in the transaction"
        },
        {
          "name": "timestamp",
          "type": "TIMESTAMP",
          "description": "Timestamp of the transaction"
        },
        {
          "name": "tx_count",
          "type": "INTEGER",
          "description": "Count of transactions"
        },
        {
          "name": "mint_count",
          "type": "INTEGER",
          "description": "Count of minting operations"
        },
        {
          "name": "swap_count",
          "type": "INTEGER",
          "description": "Count of swapping operations"
        },
        {
          "name": "burn_count",
          "type": "INTEGER",
          "description": "Count of burning operations"
        },
        {
          "name": "mint_ratio",
          "type": "FLOAT",
          "description": "Ratio of minting transactions"
        },
        {
          "name": "swap_ratio",
          "type": "FLOAT",
          "description": "Ratio of swapping transactions"
        },
        {
          "name": "burn_ratio",
          "type": "FLOAT",
          "description": "Ratio of burning transactions"
        },
        {
          "name": "transaction_type",
          "type": "VARCHAR",
          "description": "Type of transaction"
        },
        {
          "name": "transaction_value",
          "type": "FLOAT",
          "description": "Value of the transaction in USD"
        },
        {
          "name": "gas_used",
          "type": "FLOAT",
          "description": "Amount of gas used in the transaction"
        }
      ],
      "primary_key": [
        "transaction_id"
      ],
      "foreign_keys": [
        {
          "column": "token_id",
          "references": "tokens(token_id)"
        }
      ]
    },
    {
      "table_name": "liquidity_pools",
      "columns": [
        {
          "name": "pool_id",
          "type": "VARCHAR",
          "description": "Unique identifier for each liquidity pool"
        },
        {
          "name": "token0_id",
          "type": "VARCHAR",
          "description": "ID of the first token in the pool"
        },
        {
          "name": "token1_id",
          "type": "VARCHAR",
          "description": "ID of the second token in the pool"
        },
        {
          "name": "initial_liquidity_token",
          "type": "FLOAT",
          "description": "Initial amount of liquidity tokens"
        },
        {
          "name": "current_token",
          "type": "FLOAT",
          "description": "Current amount of tokens in the pool"
        },
        {
          "name": "initial_liquidity_eth",
          "type": "FLOAT",
          "description": "Initial amount of liquidity in Ether"
        },
        {
          "name": "current_eth",
          "type": "FLOAT",
          "description": "Current amount of Ether in the pool"
        },
        {
          "name": "creator_user_id",
          "type": "VARCHAR",
          "description": "User ID of pool creator"
        },
        {
          "name": "is_active",
          "type": "BOOLEAN",
          "description": "Indicates if the pool is currently active"
        }
      ],
      "primary_key": [
        "pool_id"
      ],
      "foreign_keys": [
        {
          "column": "token0_id",
          "references": "tokens(token_id)"
        },
        {
          "column": "token1_id",
          "references": "tokens(token_id)"
        },
        {
          "column": "creator_user_id",
          "references": "users(user_id)"
        }
      ]
    },
    {
      "table_name": "rugpull_events",
      "columns": [
        {
          "name": "event_id",
          "type": "VARCHAR",
          "description": "Unique identifier for each rug pull event"
        },
        {
          "name": "pool_id",
          "type": "VARCHAR",
          "description": "ID of the liquidity pool involved"
        },
        {
          "name": "is_rugpull",
          "type": "BOOLEAN",
          "description": "Indicates if a rug pull was detected"
        },
        {
          "name": "before_rugpull_eth",
          "type": "FLOAT",
          "description": "Amount of Ether before the rug pull"
        },
        {
          "name": "after_rugpull_eth",
          "type": "FLOAT",
          "description": "Amount of Ether after the rug pull"
        },
        {
          "name": "rugpull_change",
          "type": "FLOAT",
          "description": "Change in Ether due to rug pull"
        },
        {
          "name": "rugpull_timestamp",
          "type": "TIMESTAMP",
          "description": "Timestamp of the rug pull event"
        },
        {
          "name": "detection_method",
          "type": "VARCHAR",
          "description": "Method used to detect the rug pull"
        },
        {
          "name": "reported_by",
          "type": "VARCHAR",
          "description": "User ID who reported the rug pull"
        }
      ],
      "primary_key": [
        "event_id"
      ],
      "foreign_keys": [
        {
          "column": "pool_id",
          "references": "liquidity_pools(pool_id)"
        },
        {
          "column": "reported_by",
          "references": "users(user_id)"
        }
      ]
    },
    {
      "table_name": "users",
      "columns": [
        {
          "name": "user_id",
          "type": "VARCHAR",
          "description": "Unique identifier for each user"
        },
        {
          "name": "address",
          "type": "VARCHAR",
          "description": "Blockchain address of the user"
        },
        {
          "name": "role",
          "type": "VARCHAR",
          "description": "Role of the user (e.g., creator, trader, analyst)"
        },
        {
          "name": "total_lp_amount",
          "type": "FLOAT",
          "description": "Total amount of liquidity provided by the user"
        },
        {
          "name": "lp_creator_amount",
          "type": "FLOAT",
          "description": "Amount of liquidity created by the user"
        },
        {
          "name": "timestamp_creator_lp_amount",
          "type": "TIMESTAMP",
          "description": "Timestamp when the user created liquidity amount"
        },
        {
          "name": "email",
          "type": "VARCHAR",
          "description": "User's email for notifications"
        },
        {
          "name": "last_login",
          "type": "TIMESTAMP",
          "description": "Timestamp of the user's last login"
        },
        {
          "name": "status",
          "type": "VARCHAR",
          "description": "Account status (e.g., active, suspended)"
        }
      ],
      "primary_key": [
        "user_id"
      ]
    },
    {
      "table_name": "analytics",
      "columns": [
        {
          "name": "analytic_id",
          "type": "VARCHAR",
          "description": "Unique identifier for each analytic calculation"
        },
        {
          "name": "token_id",
          "type": "VARCHAR",
          "description": "ID of the token related to the analytic"
        },
        {
          "name": "transaction_id",
          "type": "VARCHAR",
          "description": "ID of the transaction related to the analytic"
        },
        {
          "name": "mint_mean_period",
          "type": "FLOAT",
          "description": "Mean period of minting operations"
        },
        {
          "name": "swap_mean_period",
          "type": "FLOAT",
          "description": "Mean period of swapping operations"
        },
        {
          "name": "burn_mean_period",
          "type": "FLOAT",
          "description": "Mean period of burning operations"
        },
        {
          "name": "swap_rate",
          "type": "FLOAT",
          "description": "Rate of swapping within the token environment"
        },
        {
          "name": "anomaly_score",
          "type": "FLOAT",
          "description": "Score indicating likelihood of an anomaly"
        },
        {
          "name": "risk_level",
          "type": "VARCHAR",
          "description": "Risk level assessed based on analytics"
        }
      ],
      "primary_key": [
        "analytic_id"
      ],
      "foreign_keys": [
        {
          "column": "token_id",
          "references": "tokens(token_id)"
        },
        {
          "column": "transaction_id",
          "references": "transactions(transaction_id)"
        }
      ]
    },
    {
      "table_name": "alerts",
      "columns": [
        {
          "name": "alert_id",
          "type": "VARCHAR",
          "description": "Unique identifier for each alert"
        },
        {
          "name": "event_id",
          "type": "VARCHAR",
          "description": "ID of the related event triggering the alert"
        },
        {
          "name": "description",
          "type": "VARCHAR",
          "description": "Description of the alert"
        },
        {
          "name": "timestamp",
          "type": "TIMESTAMP",
          "description": "Timestamp when the alert was generated"
        },
        {
          "name": "severity",
          "type": "VARCHAR",
          "description": "Severity level of the alert (e.g., low, medium, high)"
        },
        {
          "name": "resolved",
          "type": "BOOLEAN",
          "description": "Indicates if the alert has been resolved"
        },
        {
          "name": "resolved_timestamp",
          "type": "TIMESTAMP",
          "description": "Timestamp when the alert was resolved"
        }
      ],
      "primary_key": [
        "alert_id"
      ],
      "foreign_keys": [
        {
          "column": "event_id",
          "references": "rugpull_events(event_id)"
        }
      ]
    },
    {
      "table_name": "reports",
      "columns": [
        {
          "name": "report_id",
          "type": "VARCHAR",
          "description": "Unique identifier for each report"
        },
        {
          "name": "user_id",
          "type": "VARCHAR",
          "description": "ID of the user who created the report"
        },
        {
          "name": "created_at",
          "type": "TIMESTAMP",
          "description": "Timestamp when the report was created"
        },
        {
          "name": "content",
          "type": "TEXT",
          "description": "Detailed content of the report"
        },
        {
          "name": "summary",
          "type": "TEXT",
          "description": "Summary of the report findings"
        },
        {
          "name": "report_type",
          "type": "VARCHAR",
          "description": "Type of report (e.g., performance, risk assessment)"
        },
        {
          "name": "audience",
          "type": "VARCHAR",
          "description": "Intended audience for the report (e.g., investors, regulators)"
        }
      ],
      "primary_key": [
        "report_id"
      ],
      "foreign_keys": [
        {
          "column": "user_id",
          "references": "users(user_id)"
        }
      ]
    },
    {
      "table_name": "trades",
      "columns": [
        {
          "name": "trade_id",
          "type": "VARCHAR",
          "description": "Unique identifier for each trade event"
        },
        {
          "name": "pool_id",
          "type": "VARCHAR",
          "description": "ID of the pool where trade occurred"
        },
        {
          "name": "swap_in",
          "type": "FLOAT",
          "description": "Amount of token swapped in"
        },
        {
          "name": "swap_out",
          "type": "FLOAT",
          "description": "Amount of token swapped out"
        },
        {
          "name": "swap_rate",
          "type": "FLOAT",
          "description": "Rate of the swap"
        },
        {
          "name": "active_period",
          "type": "FLOAT",
          "description": "Active period of the trade event"
        },
        {
          "name": "trader_user_id",
          "type": "VARCHAR",
          "description": "User ID of the trader involved"
        },
        {
          "name": "trade_timestamp",
          "type": "TIMESTAMP",
          "description": "Timestamp of when the trade occurred"
        }
      ],
      "primary_key": [
        "trade_id"
      ],
      "foreign_keys": [
        {
          "column": "pool_id",
          "references": "liquidity_pools(pool_id)"
        },
        {
          "column": "trader_user_id",
          "references": "users(user_id)"
        }
      ]
    },
    {
      "table_name": "historical_data",
      "columns": [
        {
          "name": "history_id",
          "type": "VARCHAR",
          "description": "Unique identifier for historical data entry"
        },
        {
          "name": "token_id",
          "type": "VARCHAR",
          "description": "ID of the token related to the data"
        },
        {
          "name": "pool_id",
          "type": "VARCHAR",
          "description": "ID of the pool related to the data"
        },
        {
          "name": "timestamp",
          "type": "TIMESTAMP",
          "description": "Timestamp of the data entry"
        },
        {
          "name": "data_point",
          "type": "FLOAT",
          "description": "Value of the data point"
        },
        {
          "name": "data_type",
          "type": "VARCHAR",
          "description": "Type of historical data"
        },
        {
          "name": "source",
          "type": "VARCHAR",
          "description": "Source of the historical data"
        }
      ],
      "primary_key": [
        "history_id"
      ],
      "foreign_keys": [
        {
          "column": "token_id",
          "references": "tokens(token_id)"
        },
        {
          "column": "pool_id",
          "references": "liquidity_pools(pool_id)"
        }
      ]
    }
  ]
}
